require dirname(__DIR__).'/bootstrap.php';helper(['date_time','general','currency','form']);$db=require dirname(__DIR__).'/Increment02/isolated_database.php';$p=$f=0;$ok=function($v,$m)use(&$p,&$f){echo($v?'[PASS] ':'[FAIL] ').$m.PHP_EOL;$v?$p++:$f++;};$throws=function($fn,$text){try{$fn();return false;}catch(Throwable$e){return str_contains($e->getMessage(),$text);}};
try{$service=new App\Services\Fiscal\CreditNoteService($db);$user=(int)$db->table('users')->where(['is_admin'=>1,'deleted'=>0])->get(1)->getRow()->id;$selected=null;$sourceItem=null;foreach($service->eligibleDocuments()as$doc){$items=$db->table('fiscal_document_items')->where('fiscal_document_id',$doc->id)->get()->getResult();foreach($items as$item)if(bccomp((string)$item->quantity,'6',6)>=0){$selected=$doc;$sourceItem=$item;break 2;}}if(!$selected)throw new RuntimeException('Sin concepto de al menos 6 unidades.');$id=$service->create((int)$selected->id,$user);$ctx=$service->context($id);foreach($ctx['items']as$line)if((int)$line->source_fiscal_document_item_id!==(int)$sourceItem->id)$service->removeItem($id,(int)$line->id);$ctx=$service->context($id);$line=$ctx['items'][0];$unitBefore=(string)$line->unit_value;$service->update($id,[(int)$line->id=>'6'],(string)$ctx['note']->issue_date,$user);$ctx=$service->context($id);$expected=bcmul((string)$sourceItem->line_total,bcdiv('6',(string)$sourceItem->quantity,12),6);$ok(bccomp((string)$ctx['items'][0]->quantity,'6',6)===0,'Cantidad 80→6 (o equivalente) queda persistida.');$ok(bccomp((string)$ctx['note']->total,$expected,2)===0,'Cantidad parcial recalcula total proporcional de la Nota.');$ok(bccomp((string)$ctx['items'][0]->unit_value,$unitBefore,6)===0,'Valor unitario original permanece inmutable.');$ok($ctx['review']['ready']===true,'Revisión fiscal usa el total parcial guardado.');$xml=$service->buildXml($id);$ok(str_contains($xml,'Cantidad="6.000000"')&&str_contains($xml,'Total="'.bcadd($ctx['note']->total,'0',2).'"'),'Preview/XML usa cantidad y total recalculados.');$ok($throws(fn()=>$service->update($id,[],(string)$ctx['note']->issue_date,$user),'Capture al menos'),'Payload sin cantidades devuelve mensaje específico.');$ok($throws(fn()=>$service->update($id,[(int)$line->id=>bcadd((string)$sourceItem->quantity,'1',6)],(string)$ctx['note']->issue_date,$user),'cantidad acreditada'),'Cantidad mayor a la acreditable devuelve mensaje específico.');$service->removeItem($id,(int)$line->id);$ctx=$service->context($id);$ok(bccomp((string)$ctx['note']->total,'0',6)===0,'Quitar fila recalcula total a cero.');$view=file_get_contents(APPPATH.'Views/credit_notes/edit.php');$controller=file_get_contents(APPPATH.'Controllers/Credit_notes.php');$ok(str_contains($view,'BigInt')&&str_contains($view,"on('input change',recalculate)"),'UI recalcula fila, impuestos y total sin float.');$ok(str_contains($view,'credit-note-save-error')&&str_contains($controller,"'csrf'=>"),'AJAX presenta el mensaje backend y renueva CSRF.');$ok(!str_contains($view,'spinner-border')&&!str_contains($view,'fa-spinner'),'Generador no contiene loader persistente.');}catch(Throwable$e){echo'[FAIL] '.get_class($e).': '.$e->getMessage().' '.$e->getFile().':'.$e->getLine().PHP_EOL;$f++;}echo"TOTAL PASS=$p FAIL=$f".PHP_EOL;exit($f?1:0);